const BIND_DEF={'rage.enabled':{key:'',mode:'Always'},'rage.doubletap':{key:'KeyF',mode:'Toggle'},'rage.hideshots':{key:'KeyH',mode:'Toggle'},'rage.quickpeek':{key:'KeyX',mode:'Hold'},'rage.ovr':{key:'KeyJ',mode:'Toggle'},'rage.fbaim':{key:'KeyK',mode:'Toggle'},'rage.fsafe':{key:'',mode:'Hold'},
 'vis.third':{key:'KeyV',mode:'Toggle'},'aa.enabled':{key:'',mode:'Always'},'aa.freestand':{key:'KeyZ',mode:'Toggle'},'aa.edge':{key:'',mode:'Toggle'},'aa.inverter':{key:'KeyI',mode:'Toggle'},'aa.manleft':{key:'ArrowLeft',mode:'Toggle'},'aa.manright':{key:'ArrowRight',mode:'Toggle'},'aa.manback':{key:'ArrowDown',mode:'Toggle'},
 'aa.fakeduck':{key:'KeyE',mode:'Hold'},'aa.slowwalk':{key:'ShiftLeft',mode:'Hold'},'misc.edgejump':{key:'AltLeft',mode:'Hold'},'legit.trigger':{key:'',mode:'Always'}};
(function walk(o,p=''){for(const[k,v]of Object.entries(o)){const path=p?p+'.'+k:k;if(typeof v==='boolean'&&!BIND_DEF[path])BIND_DEF[path]={key:'',mode:'Toggle'};else if(v&&typeof v==='object'&&!Array.isArray(v))walk(v,path);}})(CFG_DEF);
const binds=merge(clone(BIND_DEF),store.get('hs3_binds',null));
for(const[path,b]of Object.entries(binds))if(b.mode==='Hold'){const parts=path.split('.');let o=cfg;for(const k of parts.slice(0,-1))o=o?.[k];if(o&&typeof o[parts.at(-1)]==='boolean')o[parts.at(-1)]=false;}
const SET_DEF={name:'super',server:'',quality:'Средне',showfps:true,master:.8,sfx:1,music:.45,sens:1.8,fov:90,cursorKey:'Backquote',xh:{color:'#5eff6a',len:7,gap:4,thick:2,dot:false,outline:true}};
