let settingReader=null,settingWriter=null;
const getP=p=>settingReader?settingReader(p):p.split('.').reduce((o,k)=>o[k],cfg);
const setP=(p,v)=>{if(settingWriter&&settingWriter(p,v))return;const k=p.split('.');k.slice(0,-1).reduce((o,x)=>o[x],cfg)[k[k.length-1]]=v;};
const RANKS=['Silver Hippo I','Silver Hippo II','Silver Hippo III','Silver Hippo IV','Silver Hippo Elite','Silver Hippo Elite Master','Gold Hippo I','Gold Hippo II','Gold Hippo III','Gold Hippo Master','Master Hippo I','Master Hippo II','Master Hippo Elite','Distinguished Master Hippo','Legendary Hippo','Legendary Hippo Master','Supreme Master First Hippo','The Global Hippo Elite'];
