 g_ak(pos){const d=bus(pos,true,1000);noise(d,.28,1,'lowpass',6500,300,.8);noise(d,.04,.6,'highpass',3000,0,.6);tone(d,'sine',140,45,.16,.85);tone(d,'square',95,50,.06,.12);},
 g_awp(pos){const d=bus(pos,true,2400);noise(d,.8,1,'lowpass',9000,160,.6);noise(d,.08,.9,'highpass',2500,0,.6);tone(d,'sine',110,28,.45,1);tone(d,'triangle',60,25,.6,.5);},
 g_scar(pos){const d=bus(pos,true,1300);noise(d,.35,1,'lowpass',7000,240,.7);noise(d,.05,.6,'highpass',3200,0,.6);tone(d,'sine',150,40,.2,.85);},
 g_r8(pos){const d=bus(pos,true,1600);noise(d,.55,1,'lowpass',4500,180,.8);tone(d,'sine',100,30,.3,1);noise(d,.04,.4,'bandpass',2500,0,5,0);},
 cock(){const d=bus(null,false,500);noise(d,.04,.3,'bandpass',2500,0,6);tone(d,'square',1400,0,.02,.05,.06);},
