 boom(pos){const d=bus(pos,true,3200);noise(d,1.4,1.2,'lowpass',3500,60,.6);tone(d,'sine',70,22,1,1.2);noise(d,.12,.8,'highpass',1800,0,.5);tone(d,'sawtooth',45,20,.8,.25);},
