 buy(){const d=bus(null,false,900);tone(d,'square',1568,0,.06,.06);tone(d,'square',2093,0,.12,.06,.06);noise(d,.08,.18,'bandpass',5000,0,3,.12);},
 nomoney(){const d=bus(null,false,500);tone(d,'square',220,180,.18,.1);},
