const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});
renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.autoClear=false;
renderer.domElement.id='gl';document.body.prepend(renderer.domElement);
let ctxLost=false;
renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();ctxLost=true;const b=$('#ctxlost');if(b)b.style.display='flex';},false);
renderer.domElement.addEventListener('webglcontextrestored',()=>{ctxLost=false;const b=$('#ctxlost');if(b)b.style.display='none';},false);
const scene=new THREE.Scene();scene.fog=new THREE.Fog('#e9d3ab',2600,9500);
const camera=new THREE.PerspectiveCamera(74,innerWidth/innerHeight,2,14000);camera.rotation.order='YXZ';
const ANISO=Math.min(8,renderer.capabilities.getMaxAnisotropy());
function canvasTex(size,draw,rep=true){const c=document.createElement('canvas');c.width=c.height=size;const g=c.getContext('2d');draw(g,size);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;if(rep)t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=ANISO;t.userData.canvas=c;return t;}
function speck(g,s,n,al,cols){for(let i=0;i<n;i++){g.fillStyle=cols[(Math.random()*cols.length)|0];g.globalAlpha=Math.random()*al;const r=Math.random()*2+.5;g.fillRect(Math.random()*s,Math.random()*s,r,r);}g.globalAlpha=1;}
function blot(g,s,n,cols,rmin,rmax,al){for(let i=0;i<n;i++){const x=Math.random()*s,y=Math.random()*s,r=rnd(rmin,rmax),c=pick(cols);for(const ox of[-s,0,s])for(const oy of[-s,0,s]){const gr=g.createRadialGradient(x+ox,y+oy,0,x+ox,y+oy,r);gr.addColorStop(0,`rgba(${c},${al})`);gr.addColorStop(1,`rgba(${c},0)`);g.fillStyle=gr;g.fillRect(x+ox-r,y+oy-r,2*r,2*r);}}}
