 const build=(T,par)=>{for(const k in T){const m=hMesh(T[k],mat(k),par);m.userData.k=k;if(k==='v'||k==='p')team_.push(m);}};
 build(HT.body,body);const head=new THREE.Group();head.position.set(0,62,-2);body.add(head);build(HT.head,head);
 const lids=[-1,1].map(sd=>{const l=hMesh(GS,mS,head,false);l.scale.set(4.35,4.85,3.35);l.position.set(sd*6.3,15,-10.3);l.visible=false;return l;});const helmet=hMesh(HT.helmet,mH,head);helmet.userData.k='h';team_.push(helmet);const strap=hMesh(HT.strap,HM.d,head);helmet.visible=strap.visible=false;
 const legL=new THREE.Group(),legR=new THREE.Group();legL.position.set(-10,28,0);legR.position.set(10,28,0);body.add(legL,legR);build(HT.leg,legL);build(HT.leg,legR);
 const arms=new THREE.Group();arms.position.set(0,54,-2);body.add(arms);const armsR=new THREE.Group(),armsP=new THREE.Group();arms.add(armsR,armsP);build(HT.armsR,armsR);build(HT.armsP,armsP);armsP.visible=false;
