const gunCache={};function gunT(id){if(!GUNDEF[id])return null;if(!gunCache[id]){const B=new PB();const info=GUNDEF[id](B);if(GDET[id])GDET[id](B);gunCache[id]={geo:B.build(),parts:B.L,...info};}return gunCache[id];}
// 2D icon from gun parts (side view)
const iconCache={};
function gunIcon(id,col='#e6eaf2',w=180,h=64){const key=id+col+w;if(iconCache[key])return iconCache[key];const T=gunT(id);if(!T)return'';const c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d');
 const quads=[];const bx=[-.5,.5];for(const k in T.parts)for(const p of T.parts[k]){if(p.g===GTor||k==='l')continue;const pos=new V(),q=new THREE.Quaternion(),s=new V();p.m.decompose(pos,q,s);const isC=p.g===GC||p.g===GTap,isS=p.g===GS;
  const cs=[];for(const a of[-.5,.5])for(const b of[-.5,.5])for(const d of[-.5,.5]){const v=new V(isS?a*2:a*(isC?2:1),b,isS?d*2:d*(isC?2:1));if(isS)v.y=b*2;v.multiply(s).applyQuaternion(q).add(pos);cs.push(v);}
  let mnz=1e9,mxz=-1e9,mny=1e9,mxy=-1e9;for(const v of cs){mnz=Math.min(mnz,v.z);mxz=Math.max(mxz,v.z);mny=Math.min(mny,v.y);mxy=Math.max(mxy,v.y);}quads.push({k,cs,mnz,mxz,mny,mxy,isS,isC,q,pos,s});}
 let Z0=1e9,Z1=-1e9,Y0=1e9,Y1=-1e9;for(const q of quads){Z0=Math.min(Z0,q.mnz);Z1=Math.max(Z1,q.mxz);Y0=Math.min(Y0,q.mny);Y1=Math.max(Y1,q.mxy);}
 const sc=Math.min((w-8)/(Z1-Z0),(h-8)/(Y1-Y0)),ox=w/2+(Z1+Z0)/2*sc,oy=h/2+(Y1+Y0)/2*sc;g.fillStyle=col;
 for(const q of quads){g.globalAlpha=q.k==='k'?1:q.k==='w'?.75:.9;if(q.isS){g.beginPath();g.ellipse(ox-q.pos.z*sc,oy-q.pos.y*sc,Math.max(1,(q.mxz-q.mnz)/2*sc),Math.max(1,(q.mxy-q.mny)/2*sc),0,0,7);g.fill();continue;}
  const loc=[[-.5,-.5],[.5,-.5],[.5,.5],[-.5,.5]].map(([b,d])=>{const v=new V(0,b,d*(q.isC?2:1));if(q.isC){v.set(0,b,0);}return v;});
  // project oriented box onto z-y: take hull of its 8 corners
  const P=q.cs.map(v=>[ox-v.z*sc,oy-v.y*sc]);P.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);const cr=(o,a,b)=>(a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0]);const lo=[],up=[];for(const p of P){while(lo.length>=2&&cr(lo[lo.length-2],lo[lo.length-1],p)<=0)lo.pop();lo.push(p);}for(let i=P.length-1;i>=0;i--){const p=P[i];while(up.length>=2&&cr(up[up.length-2],up[up.length-1],p)<=0)up.pop();up.push(p);}
  const hull=lo.slice(0,-1).concat(up.slice(0,-1));g.beginPath();hull.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]));g.closePath();g.fill();}
 return iconCache[key]=c.toDataURL();}
// ================= SKINS =================
const SKINS={
 ssg:{'Hippo Fade':['#eb4b4b',g=>grad(g,['#ff4fd8','#7c3aed','#22d3ee','#a7f3d0'],1)],'Dragon Hippo':['#eb4b4b',g=>scales(g,'#1f5f2c','#e8c547')],'Asiimov':['#eb4b4b',g=>asii(g)],
  'Neo-Noir':['#d32ce6',g=>noir(g)],'Case Hardened':['#d32ce6',g=>blue(g)],'Sand Dune':['#4b69ff',g=>{g.fillStyle='#c9a46a';g.fillRect(0,0,256,256);speck(g,256,4000,.4,['#8a6a3a','#e8d2a0']);}]},
 dgl:{'Gold Rush':['#eb4b4b',g=>{grad(g,['#fbbf24','#b45309','#fde68a'],1);g.strokeStyle='rgba(60,20,0,.5)';for(let i=0;i<30;i++){g.beginPath();g.arc(rnd(0,256),rnd(0,256),rnd(5,25),0,7);g.stroke();}}],
  'Blaze':['#d32ce6',g=>grad(g,['#1a0500','#ff5a00','#ffd000','#fff3a0'],0)],'Hippo Fade':['#eb4b4b',g=>grad(g,['#ff4fd8','#7c3aed','#22d3ee'],1)],'Neo-Noir':['#d32ce6',g=>noir(g)],'Asiimov':['#eb4b4b',g=>asii(g)]},
 knife:{'Doppler':['#ffd700',g=>doppler(g,['#1b0033','#7a1fa2','#0b0b2a','#c026d3'])],'Sapphire':['#ffd700',g=>doppler(g,['#001a4d','#0f5bd6','#00113a','#38bdf8'])],'Fade':['#ffd700',g=>grad(g,['#ffd400','#ff4fd8','#7c3aed'],1)],
  'Crimson Web':['#ffd700',g=>web(g)],'Case Hardened':['#ffd700',g=>blue(g)]}};
function grad(g,cols,diag){const gr=diag?g.createLinearGradient(0,0,256,180):g.createLinearGradient(0,256,0,0);cols.forEach((c,i)=>gr.addColorStop(i/(cols.length-1),c));g.fillStyle=gr;g.fillRect(0,0,256,256);speck(g,256,2500,.2,['#fff','#000']);}
function scales(g,a,b){g.fillStyle=a;g.fillRect(0,0,256,256);for(let y=0;y<256;y+=16)for(let x=0;x<256;x+=16){g.fillStyle=`rgba(${Math.random()<.3?'232,197,71':'40,120,60'},.7)`;g.beginPath();g.arc(x+(y/16%2)*8,y,9,0,Math.PI);g.fill();}g.fillStyle=b;g.globalAlpha=.5;g.font='bold 60px Arial';g.fillText('龍',90,150);g.globalAlpha=1;}
function asii(g){g.fillStyle='#f3f1ec';g.fillRect(0,0,256,256);g.fillStyle='#ff6a13';g.beginPath();g.moveTo(0,140);g.lineTo(256,60);g.lineTo(256,120);g.lineTo(0,200);g.fill();g.fillStyle='#111';g.fillRect(0,200,256,56);g.fillStyle='#ff6a13';g.fillRect(0,206,256,6);}
function noir(g){g.fillStyle='#111';g.fillRect(0,0,256,256);g.strokeStyle='#fff';g.lineWidth=3;for(let i=0;i<14;i++){g.beginPath();g.moveTo(rnd(0,256),rnd(0,256));g.bezierCurveTo(rnd(0,256),rnd(0,256),rnd(0,256),rnd(0,256),rnd(0,256),rnd(0,256));g.stroke();}g.fillStyle='#e11d48';g.beginPath();g.arc(170,90,40,0,7);g.fill();}
function blue(g){g.fillStyle='#8a8a7a';g.fillRect(0,0,256,256);blot(g,256,40,['40,90,200','200,160,60','30,50,120'],15,60,.7);}
function doppler(g,cols){grad(g,cols,1);blot(g,256,30,['255,255,255','0,0,0','200,40,255'],10,40,.25);}
function web(g){g.fillStyle='#8b0d0d';g.fillRect(0,0,256,256);g.strokeStyle='rgba(0,0,0,.8)';g.lineWidth=2;for(let r=20;r<380;r+=34){g.beginPath();g.arc(128,128,r,0,7);g.stroke();}for(let a=0;a<12;a++){g.beginPath();g.moveTo(128,128);g.lineTo(128+Math.cos(a/2)*400,128+Math.sin(a/2)*400);g.stroke();}}
const skinCache={};
function skinTex(w,name){const k=w+'|'+name;if(!skinCache[k]){const def=SKINS[w][name]||Object.values(SKINS[w])[0];skinCache[k]=canvasTex(256,(g)=>def[1](g),true);}return skinCache[k];}
function skinThumb(w,name){return skinTex(w,name).userData.canvas.toDataURL();}
function redline(g){g.fillStyle='#141414';g.fillRect(0,0,256,256);speck(g,256,3000,.25,['#333','#000']);g.fillStyle='#d11a1a';for(const y of[70,160]){g.fillRect(0,y,256,10);g.fillRect(0,y+16,256,3);}}
