// ================= PHYSICS =================
function ovl(p,s,h){return p.x+PR>s.min.x&&p.x-PR<s.max.x&&p.z+PR>s.min.z&&p.z-PR<s.max.z&&p.y+h>s.min.y&&p.y<s.max.y;}
function resolveH(e,ax){const p=e.pos,v=e.vel;for(const s of solids){if(!ovl(p,s,PH))continue;const st=s.max.y-p.y;
 if(e.wasGround&&st>0&&st<=18.5){const ty=p.y;p.y=s.max.y;if(freeAt(p))continue;p.y=ty;}
 const c=(s.min[ax]+s.max[ax])/2;p[ax]=p[ax]<c?s.min[ax]-PR-.001:s.max[ax]+PR+.001;v[ax]=0;e.bumped=true;}}
function moveEnt(e,dt){const p=e.pos,v=e.vel;e.bumped=false;const vy0=v.y;p.x+=v.x*dt;resolveH(e,'x');p.z+=v.z*dt;resolveH(e,'z');const was=e.onGround;e.onGround=false;p.y+=v.y*dt;
 for(const s of solids){if(!ovl(p,s,PH))continue;if(v.y<=0&&s.max.y-p.y<40){p.y=s.max.y;e.onGround=true;v.y=0;}else if(v.y>0){p.y=s.min.y-PH-.01;v.y=0;}}
 if(p.y<-500){p.set(0,0,0);v.set(0,0,0);}
 if(!was&&e.onGround&&vy0<-250)e.landV=-vy0;}
function friction(v,dt,k=1){const sp=Math.hypot(v.x,v.z);if(sp<.1){v.x=v.z=0;return;}const drop=Math.max(sp,STOPSPD)*FRIC*k*dt;const ns=Math.max(sp-drop,0)/sp;v.x*=ns;v.z*=ns;}
