const _tmpH={t0:0,t1:0,ax:0};
function walls(o,d,maxT){WN=0;for(const s of solids){if(WN>=WH.length)break;if(rayBox(o,d,s.min,s.max,_tmpH)&&_tmpH.t0<maxT){let i=WN++;while(i>0&&WH[i-1].t0>_tmpH.t0){const a=WH[i];WH[i]=WH[i-1];WH[i-1]=a;i--;}WH[i].t0=_tmpH.t0;WH[i].t1=_tmpH.t1;WH[i].ax=_tmpH.ax;WH[i].surface=s.surface||'stone';}}return WN;}
