function traceBullet(o,d,pen,shooter,penPow=72){let best=null,bt=8192;const st=shooter&&shooter.team;
 for(const b of bots)if(b.alive&&b.active&&b!==shooter&&(G.dm||!st||b.team!==st)){updHB(b);for(const h of b.hb){const t=raySphere(o,d,h.c,h.r);if(t>0&&t<bt){bt=t;best={t,bot:b,hb:h};}}}
 let pens=0,end=8192,ax=-1,damageScale=1,budget=penPow;const n=walls(o,d,bt);const maxP=pen===true?1:(pen||0);
 for(let i=0;i<n;i++){const w=WH[i];const P=Surface46[w.surface]||Surface46.stone,thick=w.t1-w.t0,cost=thick*P.resistance+P.entry;if(pens<maxP&&thick<=P.maxDepth&&cost<=budget){pens++;budget-=cost;damageScale*=P.loss*Math.exp(-thick*P.attenuation);continue;}end=w.t0;ax=w.ax;break;}
 if(best&&best.t<end)return{hit:best,end:best.t,pens,damageScale,ax:-1};
 if(ax>=0){_nrm.set(0,0,0);_nrm.setComponent(ax,d.getComponent(ax)>0?-1:1);}
 return{hit:null,end,pens:0,damageScale:0,ax};}
function smokeBlock(a,b){for(const S of smokes){if(S.t<=0||S.r<30)continue;const dx=b.x-a.x,dy=b.y-a.y,dz=b.z-a.z,L2=dx*dx+dy*dy+dz*dz||1;const t=clamp(((S.p.x-a.x)*dx+(S.p.y+60-a.y)*dy+(S.p.z-a.z)*dz)/L2,0,1);
 const px=a.x+dx*t-S.p.x,py=a.y+dy*t-S.p.y-60,pz=a.z+dz*t-S.p.z;if(px*px+py*py*1.4+pz*pz<S.r*S.r*.75)return true;}return false;}
