 Hud46.hotkeys(rows);
 const spc=$('#specs');const sl=!p.alive?[]:G.mp?bots.filter(b=>b.remote&&b.active&&!b.alive):bots.filter(b=>b.active&&!b.alive&&b.team===p.team&&!G.dm);spc.style.display=cfg.misc.specs&&sl.length?'block':'none';
 if(sl.length)$('#spl').innerHTML=sl.map(b=>`<div class="r">${esc(b.name)}<span>[1st]</span></div>`).join('');
