// ================= INVENTORY / SHOP / COSMETICS =================
const inv=merge({coins:3000,own:[],eq:{kf:'std',dfx:'fall',tr:'std'},hist:[],seen:0},store.get('hs4_inv',null));
function saveInv(){store.set('hs4_inv',inv);}
const COSM={
 kf:[['std','Стандарт',0,'c'],['nl','Neverlose',400,'u'],['blood','Кровавый',500,'u'],['pink','Неон-розовый',500,'u'],['ice','Ледяной',600,'r'],['matrix','Матрица',700,'r'],['fire','Огненный',800,'r'],['gold','Золотой',900,'m'],['glitch','Глитч',1000,'m'],['rgb','Радуга',1200,'l'],['void','Бездна',1500,'x']],
 dfx:[['fall','Падение',0,'c'],['shrink','Сжатие',400,'u'],['pop','Лопнул',500,'u'],['dissolve','Растворение',600,'r'],['explode','Взрыв конфетти',700,'r'],['ash','Пепел',800,'r'],['freeze','Заморозка',900,'m'],['zap','Удар молнии',1000,'m'],['disco','Диско-смерть',1100,'m'],['ascend','Вознесение',1200,'l'],['rocket','Ракета',1500,'l'],['gold','Золотая статуя',2000,'x']],
 tr:[['std','Стандарт (цвет из чита)',0,'c'],['laser','Красный лазер',500,'u'],['rgb','Радуга',600,'r'],['ghost','Призрачный',700,'r'],['gold','Золото',800,'m'],['plasma','Плазма',1000,'m'],['zap','Молния',1200,'l']]};
for(const k in COSM)COSM[k]=COSM[k].map(([id,n,p,r])=>({id,n,price:p,rar:r,cat:k}));
const CATN={ag:'Агенты',kf:'Киллфиды',dfx:'Виды смерти',tr:'Трейсеры'};
const DFXD={fall:'Классическое падение на спину.',shrink:'Враг сжимается в точку.',pop:'Бегемот лопается как шарик.',dissolve:'Тело растворяется в искрах.',explode:'Взрыв разноцветного конфетти.',ash:'Обугливается и рассыпается в пепел.',freeze:'Замерзает и разбивается на осколки.',zap:'С неба бьёт молния.',disco:'Танцует диско и исчезает.',ascend:'Улетает на небо с нимбом.',rocket:'Улетает ракетой и взрывается фейерверком.',gold:'Превращается в золотую статую.'};
function itemOf(cat,id){return cat==='ag'?AGB[id]:COSM[cat].find(x=>x.id===id);}
function owns(cat,id){const it=itemOf(cat,id);return !!it&&(!it.price||inv.own.includes(cat+':'+id));}
function equipped(cat,id){return cat==='ag'?cfg.skins.agent===id:inv.eq[cat]===id;}
function buyItem(cat,id){const it=itemOf(cat,id);if(!it||owns(cat,id))return false;if(inv.coins<it.price){SND.nomoney();return false;}inv.coins-=it.price;inv.own.push(cat+':'+id);saveInv();SND.buy();return true;}
function equipItem(cat,id){if(!owns(cat,id))return false;if(cat==='ag'){cfg.skins.agent=id;applyCfg();saveAll();if(NET.conn)NET.prof();}else{inv.eq[cat]=id;saveInv();if(cat==='dfx'&&NET.conn)NET.prof();}SND.click();return true;}
const CASE_PRICE=750;
function rollCase(){const pool=[];const W={c:0,u:40,r:26,m:16,l:9,x:4};for(const a of AGENT_LIST)if(a.price&&!owns('ag',a.id))pool.push(['ag',a]);for(const k in COSM)for(const it of COSM[k])if(it.price&&!owns(k,it.id))pool.push([k,it]);
 if(!pool.length)return null;let tot=0;for(const[,it]of pool)tot+=W[it.rar]||10;let r=Math.random()*tot;for(const p of pool){r-=W[p[1].rar]||10;if(r<=0)return p;}return pool[0];}
function strip(){const L=[];for(const a of AGENT_LIST)if(a.price)L.push(['ag',a]);for(const k in COSM)for(const it of COSM[k])if(it.price)L.push([k,it]);return L;}
function awardCoins(n,why){if(n<=0)return;inv.coins+=n;saveInv();}
// ---- tracers ----
let trI=0;function trBeam(a,b,col){const t=inv.eq.tr;trI++;
 if(t==='std')return beam(a,b,col);
 if(t==='rgb')return beam(a,b,`hsl(${(trI*47)%360},95%,60%)`,1.6,1.6,true);
 if(t==='laser')return beam(a,b,'#ff1a1a',.9,.7,true);
 if(t==='gold')return beam(a,b,'#ffd34d',1.8,1.5,true);
 if(t==='plasma'){beam(a,b,'#b14dff',1.2,3.2,true);return beam(a,b,'#ffffff',.6,.8,true);}
 if(t==='ghost')return beam(a,b,'#e6f0ff',2.8,2.2,true);
 if(t==='zap'){let p=a.clone();const n=7;for(let i=1;i<=n;i++){const q=a.clone().lerp(b,i/n);if(i<n)q.add(new V(rnd(-6,6),rnd(-6,6),rnd(-6,6)));beam(p,q,'#9fd0ff',.5,1.8,true);p=q;}}}
// ---- death effects ----
const iceMat=new THREE.MeshStandardMaterial({color:'#bfeaff',emissive:'#4fc3f7',emissiveIntensity:.45,metalness:.3,roughness:.08,transparent:true,opacity:.82});
const ashMat=new THREE.MeshStandardMaterial({color:'#151515',roughness:1});
const goldStat=new THREE.MeshStandardMaterial({color:'#e2b33a',metalness:1,roughness:.18,emissive:'#4a3500',emissiveIntensity:.3});
const discoMat=new THREE.MeshStandardMaterial({color:'#ffffff',emissive:'#ff00ff',emissiveIntensity:.9,roughness:.3});
function setDfx(b,id){b.dfx=id||'fall';b.dfT=0;b.dfE=0;}
function deathAnim(b,h,dt){const R=h.root,t=(b.dfT=(b.dfT||0)+dt),k=b.dfx||'fall';b.dfxMat=null;const c=b.pos.clone().add(new V(0,42,0));
 const fall=()=>{b.die=Math.max(0,b.die-dt*2.5);R.rotation.x=-(1-b.die)*Math.PI/2;};const once=f=>{if(!b.dfE){b.dfE=1;f();}};
 switch(k){
  case'shrink':{const s=Math.max(.001,1-t*1.6);R.scale.set(s,s,s);h.body.rotation.y=b.bodyYaw+t*12;if(s<=.001)R.visible=false;break;}
  case'pop':once(()=>emit(c,120,['#ffb3c4','#ffffff',b.model.mats.mS.color.getStyle()],520,1.1,600,150));{const s=1+Math.min(1,t*4)*.7;R.scale.set(s,s,s);if(t>.25)R.visible=false;}break;
  case'dissolve':R.scale.set(1,Math.max(.01,1-t*.9),1);if(t<1.1&&Math.random()<.8)emit(c.clone().setY(b.pos.y+rnd(0,70*(1-t*.9))),6,['#ffd36b','#ff8a3d','#ffffff'],60,1,-140,60);if(t>1.1)R.visible=false;break;
  case'explode':once(()=>{emit(c,160,['#ff4fd8','#3b82f6','#ffe066','#7dff9a','#ff6b6b'],560,1.6,500,220);SND.boom&&SND.boom(b.pos);});R.visible=false;break;
  case'ash':b.dfxMat=ashMat;if(t<.5)fall();else{R.scale.set(1,Math.max(.01,1-(t-.5)*1.1),1);if(Math.random()<.7)emit(c.clone().setY(b.pos.y+10),5,['#222','#444','#666'],70,1.4,200,30);if(t>1.4)R.visible=false;}break;
  case'freeze':b.dfxMat=iceMat;if(t>.9){once(()=>emit(c,140,['#bfeaff','#7dd3fc','#ffffff'],420,1.3,700,120));R.visible=false;}break;
  case'zap':once(()=>lightning(b.pos.clone().add(new V(0,40,0))));b.dfxMat=t>.15?ashMat:null;fall();if(t>1.6){R.scale.set(1,Math.max(.01,1-(t-1.6)*2),1);if(t>2.1)R.visible=false;}break;
  case'disco':b.dfxMat=discoMat;discoMat.emissive.setHSL((t*2)%1,1,.5);h.body.rotation.y=b.bodyYaw+t*14;R.position.y+=Math.abs(Math.sin(t*12))*8;if(t>1.6){once(()=>emit(c,90,['#ff00ff','#00ffff','#ffff00'],400,1,500,150));R.visible=false;}break;
  case'ascend':R.position.y+=t*t*60;h.body.rotation.y=b.bodyYaw+t*2;if(Math.random()<.5)emit(c.clone().setY(R.position.y+30),3,['#fff7c2','#ffffff'],40,1,-60,0);{const s=Math.max(.01,1-Math.max(0,t-1.8));R.scale.set(s,s,s);if(s<=.01)R.visible=false;}break;
  case'rocket':{const up=Math.max(0,t-.2);R.position.y+=up*up*420;R.rotation.z=Math.sin(t*20)*.08;if(t>.2&&Math.random()<.9)emit(new V(b.pos.x,R.position.y,b.pos.z),6,['#ffb347','#ff5a1f','#888888'],60,.8,-50,-120);
   if(t>1.5){once(()=>{emit(new V(b.pos.x,R.position.y+30,b.pos.z),200,['#ff4fd8','#ffe066','#7dff9a','#3b82f6','#ffffff'],620,1.8,300,0);SND.boom&&SND.boom(b.pos);});R.visible=false;}break;}
  case'gold':b.dfxMat=goldStat;if(t<.25)once(()=>emit(c,50,['#ffd34d','#fff2b3'],260,1,300,80));if(t>3){R.scale.set(1,Math.max(.01,1-(t-3)*2),1);if(t>3.5)R.visible=false;}break;
  default:fall();}}
// ---- agent preview renderer (buy menu / thumbnails) ----
const PV={r:null,scene:new THREE.Scene(),cam:new THREE.PerspectiveCamera(26,.6,1,3000),h:null,ag:null,gun:null,t:0};
