 compatCommands(r,commands){r.compatDraw=[];if(!Array.isArray(commands))return [];const out=[];for(const c of commands.slice(0,256)){if(c?.type==='shape'){if(this.validShape(c))r.compatDraw.push(c);else this.message(r,'Некорректная render-команда');}else if(c?.type==='widget'){if(!r.widgets)r.widgets=new Map();if(r.widgets.size>=64&&!r.widgets.has(c.id))continue;const old=r.widgets.get(c.id);const init=c.value;if(c.value&&typeof c.value==='object'&&c.kind==='selectable')c.value=Object.values(c.value);r.widgets.set(c.id,c);if(c.kind!=='label'&&c.kind!=='button'){r.widgetValues[c.id]=c.value;}if(old&&this.widgetSignature(old)!==this.widgetSignature(c))r.uiChanged=true;if(!old)r.uiChanged=true;this.save();}else if(c?.type==='override'){try{this.setOverride(r,c.path,c.value);}catch(e){this.message(r,e.message);}}else if(c?.type==='widget_override'){if(!r.widgetOverrides)r.widgetOverrides=new Map();if(c.value==null)r.widgetOverrides.delete(c.id);else r.widgetOverrides.set(c.id,c.value);}else if(c?.type==='notify'){toast('<b>'+esc(c.title)+'</b><br>'+esc(c.text));}else if(c?.type==='reload_script'){setTimeout(()=>this.start(r),0);}else if(c?.type==='unload_script'){setTimeout(()=>this.stop(r),0);}else out.push(c);}return out;},
