 if(this.view==='api'){const h=document.createElement('div');h.className='lu-doc-head';h.innerHTML='<h3>Документация API</h3><button data-doc-download>Скачать .md</button>';h.querySelector('button').onclick=()=>this.download('LUA_API.md',HS_LUA_HELP);pane.appendChild(h);const nav=document.createElement('select');nav.className='lu-doc-select';nav.setAttribute('aria-label','Раздел документации');pane.appendChild(nav);const doc=document.createElement('div');doc.className='lu-doc lu-doc-formatted';pane.appendChild(doc);for(const sec of this.renderDocs(doc)){const o=document.createElement('option');o.value=sec.id;o.textContent=sec.label;nav.appendChild(o);}nav.onchange=()=>doc.querySelector('#'+nav.value)?.scrollIntoView({block:'start',behavior:'instant'});return;}
