 const r=selected();if(!r){const blank=document.createElement('div');blank.className='lu-empty';blank.innerHTML='<span class="lu-codeicon">{ }</span><h3>Твоя библиотека Lua</h3><p>Добавь скрипт или начни с готового примера.<br>Редактор открывается отдельно — без лишних панелей.</p><button class="primary">Импортировать .lua</button>';blank.querySelector('button').onclick=()=>P.querySelector('#lua-upload').click();pane.appendChild(blank);return;}
 const head=document.createElement('div');head.className='lu-detail-head';const info=document.createElement('div');const title=document.createElement('h3');title.textContent=r.name;const status=document.createElement('span');status.className='lu-status';status.dataset.luaStatus=r.id;status.dataset.state=r.status;status.textContent=({running:'Запущен',loading:'Загрузка',stopped:'Выключен',error:'Ошибка'}[r.status]);info.append(title,status);const actions=document.createElement('div');actions.className='lu-actions';const run=document.createElement('button');run.dataset.act='run';run.className='primary';run.textContent=r.enabled?'■ Остановить':'▶ Запустить';run.onclick=()=>{r.enabled?this.stop(r):this.start(r);show();};const edit=document.createElement('button');edit.textContent='Редактор';edit.onclick=()=>this.editor(r,show);const more=document.createElement('button');more.textContent='···';more.title='Экспорт и удаление';more.onclick=()=>{const b=more.getBoundingClientRect();openPop(b.right-140,b.bottom+4,p=>{for(const[label,f]of[['Скачать .lua',()=>this.download(r.name,r.code)],['Удалить скрипт',()=>{if(confirm('Удалить '+r.name+'?')){this.stop(r);this.records=this.records.filter(x=>x!==r);this.selected=this.records[0]?.id||null;this.save();show();}}]]){const btn=document.createElement('div');btn.className='pi';btn.textContent=label;btn.onclick=()=>{closePop();f();};p.appendChild(btn);}},160);};actions.append(run,edit,more);head.append(info,actions);pane.appendChild(head);
