 if(it[0]==='history'){const r=document.createElement('div');r.className='nl-r';r.innerHTML='<span class="lb">History</span><div class="dd"></div>';const dd=r.lastChild;const names=['Disabled','Low','Medium','Maximum'],values=[0,100,200,400],upd=()=>dd.textContent=names[values.indexOf(getP('rage.backtrack'))]||getP('rage.backtrack')+' ms';upd();dd.onclick=()=>{const b=dd.getBoundingClientRect();openPop(b.left,b.bottom,p=>{for(let i=0;i<4;i++){const x=document.createElement('div');x.className='pi'+(getP('rage.backtrack')===values[i]?' on':'');x.textContent=names[i];x.onclick=()=>{setP('rage.backtrack',values[i]);applyCfg();upd();closePop();};p.appendChild(x);}p.appendChild(csBaseControl(NLCS.item('rage.backtrack')));},230);};return r;}
