 if(searchQ){const res=[];for(const tb of MENU)for(const col of tb.cols)for(const gr of col){const its=gr.it.filter(x=>String(x[2]||x[1]).toLowerCase().includes(searchQ));if(its.length)res.push({g:tb.tab+' › '+gr.g,it:its});}NLCS.generic(C,[res.filter((_,i)=>i%2===0),res.filter((_,i)=>i%2===1)]);if(!res.length)C.innerHTML='<div class="cs-no-results">Нет настроек по этому запросу</div>';return;}
