// Render original game meshes once and cache transparent cutouts. No extra RAF/context per tile.
const CSPreview={r:null,S:null,C:null,H:null,cache:{},
 init(){if(this.r)return true;try{this.r=new THREE.WebGLRenderer({alpha:true,antialias:true,preserveDrawingBuffer:true});this.r.setPixelRatio(1);this.r.setClearColor(0,0);this.r.outputColorSpace=THREE.SRGBColorSpace;this.r.toneMapping=THREE.ACESFilmicToneMapping;this.r.toneMappingExposure=1.25;this.S=new THREE.Scene();this.S.add(new THREE.HemisphereLight('#ffffff','#46526b',2.2));for(const[pos,col,power]of [[[-2,3,3],'#ffffff',3],[[3,2,-3],'#c4dcff',2]]){const l=new THREE.DirectionalLight(col,power);l.position.set(...pos);this.S.add(l);}return true;}catch(e){return false;}},
 gun(id,name){const key=id+'|'+(name||'default')+(id==='knife'?'|'+cfg.skins.knifeModel:'');if(this.cache[key])return this.cache[key];if(!this.init())return gunIcon(id,'#d0d9e6',320,150);const T=gunT(id);if(!T)return'';const g=new THREE.Group(),owned=[];for(const k in T.geo){let m=k==='p'?(wMat[id]||tpMat.p):k==='w'?mWood:k==='m'?mMet:k==='l'?mLens:mBlk;m=m.clone();if(k==='p'&&SKINS[id]){if(name==='Default'){m.map=null;m.color.set('#44474b');}else m.map=skinTex(id,name||cfg.skins[id]);}if(m.metalness!==undefined){m.metalness=Math.min(m.metalness,.38);m.roughness=Math.max(m.roughness,.38);}owned.push(m);g.add(new THREE.Mesh(T.geo[k],m));}this.S.add(g);const box=new THREE.Box3().setFromObject(g),c=box.getCenter(new V()),size=box.getSize(new V()),aspect=1.85,h=Math.max(size.y*1.5,size.z/aspect*1.22,size.x*1.6,.16);const cam=new THREE.OrthographicCamera(-h*aspect/2,h*aspect/2,h/2,-h/2,.001,100);cam.position.copy(c).add(new V(-3,.4, .45));cam.lookAt(c);this.r.setSize(370,200,false);this.r.render(this.S,cam);const u=this.r.domElement.toDataURL('image/png');this.S.remove(g);owned.forEach(m=>m.dispose());return this.cache[key]=u;},
 agent(id){const key='agent|'+id;if(this.cache[key])return this.cache[key];if(!this.init())return agentThumb(id);if(!this.H){this.H=makeHippo('#8fa3c4','#3b82f6',false,'CT');scene.remove(this.H.root);}const h=this.H;applyAgent(h,id);setHippoGun(h,'ak',true);h.gun.visible=true;h.armsR.visible=true;h.armsP.visible=false;WhiteGlow46.sync(h,false);for(const m of h.meshes)m.material=m.userData.orig;h.body.rotation.y=Math.PI+.25;h.body.position.y=0;h.head.rotation.set(0,0,0);h.root.position.set(0,0,0);h.root.rotation.set(0,0,0);this.S.add(h.root);const cam=new THREE.PerspectiveCamera(24, .68,1,1500);cam.position.set(0,50,232);cam.lookAt(0,44,0);this.r.setSize(272,400,false);this.r.render(this.S,cam);const u=this.r.domElement.toDataURL('image/png');this.S.remove(h.root);return this.cache[key]=u;}
};
