 const E=$('#cs-equipment');this.tile(E,{img:CSPreview.gun('knife',cfg.skins.knife),name:'★ '+cfg.skins.knifeModel+' · '+cfg.skins.knife,color:'#eb4b4b',fn:()=>Knife46.selector()});this.tile(E,{img:Equipment46.gloves(),name:'Gloves · Hippo tactical',color:'#eb4b4b',fn:()=>this.agents()});this.tile(E,{img:CSPreview.gun('he'),name:'HE Grenade',color:'#eb4b4b',fn:()=>this.nade('he')});this.tile(E,{img:CSPreview.gun('smoke'),name:'Smoke Grenade',color:'#b0c3d9',fn:()=>this.nade('smoke')});this.cosTile(E,'tr',NLCS.icons.effect);this.cosTile(E,'dfx',NLCS.icons.misc);
