 for(const[title,items]of cols){const col=document.createElement('div');col.className='cs-weapon-column';col.innerHTML=`<h3>${title}</h3>`;for(const[id,variant]of items){const n=variant||cfg.skins[id],w=WEAPONS.find(w=>w.id===id),name=(w?.name||id)+(n?' · '+n:'');this.tile(col,{img:CSPreview.gun(id,n),name,color:SKINS[id]?.[n]?.[0]||'#b0c3d9',fn:()=>SKINS[id]?this.skins(id,n):this.nade(id)});}$('#cs-weapon-columns').appendChild(col);}
