 skins(id,selected){this.modal((WEAPONS.find(w=>w.id===id)?.name||id)+' · Finish',(B,M)=>{B.classList.add('cs-finish-grid');for(const[n,def]of Object.entries(SKINS[id])){const b=this.tile(B,{img:CSPreview.gun(id,n),name:n,color:def[0],fn:()=>{setP('skins.'+id,n);applyCfg();saveAll();SND.accept();M.remove();renderTab();}});b.classList.add('cs-finish');b.classList.toggle('equipped',cfg.skins[id]===n);if(n===selected)b.classList.add('selected');}});},
