 cosmetics(cat){this.modal(CATN[cat],(B,M)=>{for(const it of COSM[cat]){const own=owns(cat,it.id),b=document.createElement('button');b.className='cs-cosmetic-row'+(equipped(cat,it.id)?' on':'');b.innerHTML=`<span style="color:${rarC(it.rar)}">●</span><b>${esc(it.n)}</b><small>${own?(equipped(cat,it.id)?'Equipped':'Equip'):'🔒 '+fmtN(it.price)}</small>`;b.onclick=()=>{if(own){equipItem(cat,it.id);M.remove();renderTab();}else{M.remove();toggleMenu(false);shopCat=cat;shopSel=it.id;csView='';csGo('shop');}};B.appendChild(b);}});},
 stats(){this.modal('Profile',B=>{B.innerHTML=`<div class="cs-profile-rank">${NLCS.icons.medal}<h3>${esc(rankBadge())}</h3><p>${esc(sett.name||'super')}</p><p>Level ${Math.floor(stats.xp/1000)+1} · ${fmtN(stats.xp)} XP</p><p>${fmtN(inv.coins)} coins</p></div>`;});},
 nade(id){this.modal(WEAPONS.find(w=>w.id===id)?.name||id,B=>{B.innerHTML=`<img class="cs-nade-preview" src="${CSPreview.gun(id)}"><p class="cs-note">У этой гранаты нет сменных скинов. Купить её можно в игровом меню закупки.</p>`;});}
