NLCS.family=function(i=curTab){return this.families.find(f=>f.children.some(c=>c[0]===i))?.id??6;};
NLCS.openFamily=0;
NLCS.go=function(i){curTab=i;this.openFamily=this.family(i);searchQ='';const q=$('#nl-q');if(q)q.value='';renderTab();SND.ui();};
NLCS.refreshNav=function(){const T=$('#nl-tabs');if(!T)return;T.innerHTML='';for(let j=0;j<this.families.length;j++){if(j===0||j===2){const h=document.createElement('div');h.className='nl-sec';h.textContent=j===0?'Aimbot':'Common';T.appendChild(h);}const f=this.families[j],b=document.createElement('button');b.className='nl-tab'+(this.family()===f.id?' on':'');b.dataset.tab=f.id;b.title=f.label;b.setAttribute('aria-expanded',String(this.openFamily===f.id));b.innerHTML=`<span class="ic">${f.ic}</span><span class="nl-tab-label">${f.label}</span><span class="nl-expand">${this.icons.chevron}</span>`;b.onclick=()=>{const active=this.family()===f.id;this.openFamily=this.openFamily===f.id?null:f.id;if(!active){curTab=f.children[0][0];this.rageAdvanced=false;searchQ='';$('#nl-q').value='';renderTab();}else this.refreshNav();SND.ui();};T.appendChild(b);
 if(this.openFamily===f.id){const sub=document.createElement('div');sub.className='nl-subtabs';for(const[i,label,icon]of f.children){const q=document.createElement('button');q.className='nl-subtab'+(curTab===i&&!searchQ?' on':'');q.dataset.subtab=i;q.title=label;q.innerHTML=`<span class="nl-childicon">${icon}</span><span>${label}</span>`;q.onclick=()=>{this.rageAdvanced=false;this.go(i);};sub.appendChild(q);}T.appendChild(sub);}}
};
