renderTab=function(){const special=[3,4,10,11,12,13].includes(curTab)&&!searchQ;if(!special){vxRender43();$('#nl-content>.cs-subnav')?.remove();}else{closePop();const C=$('#nl-content');C.innerHTML='';C.className='';$('#nl-head-tools').innerHTML='';$('#nl-global').style.display='none';const t=MENU[curTab];if(curTab===10){const L=document.createElement('div'),R=document.createElement('div');L.className=R.className='nl-col';C.append(L,R);for(const gr of t.cols[0])NLCS.section(L,gr.g,gr.it);const preview=document.createElement('div');preview.className='vx-cham-preview';preview.innerHTML='<div class="vx-preview-top"><span>LIVE MATERIAL</span><b id="vx-preview-label"></b></div><div id="vx-preview-canvas"></div><div class="vx-palettes"></div>';R.appendChild(preview);for(const[n,v]of Object.entries(ChamsFX.presets)){const b=document.createElement('button');b.className='vx-palette';b.dataset.preset=n;b.style.background=`linear-gradient(135deg,${v.chamsColor},${v.chamsSecondary})`;b.textContent=n;b.onclick=()=>ChamsFX.preset(n);preview.querySelector('.vx-palettes').appendChild(b);}for(const gr of t.cols[1])NLCS.section(R,gr.g,gr.it);ChamsFX.previewParent=$('#vx-preview-canvas');ChamsFX.previewFrame(true);}else if(curTab===3)NLCS.generic(C,[t.cols[0],t.cols[1].filter(g=>!['Chams','Local'].includes(g.g))]);else if(curTab===4)NLCS.generic(C,[[t.cols[0][0]],[VX_GROUPS.atmosphere]]);else NLCS.generic(C,t.cols);}
 NLCS.refreshNav();};
