ChamsFX.previewFrame=function(force=false){const parent=this.previewParent;if(!menuOpen||curTab!==10||!parent?.isConnected)return;const now=performance.now();const signature=[cfg.vis.chamsMat,cfg.vis.chamsColor,cfg.vis.chamsSecondary,cfg.vis.chamsSpeed,cfg.vis.chamsScale,cfg.vis.chamsOpacity,cfg.vis.chamsRim,cfg.skins.agent].join('|');if(!force&&(now-(this.prevFrame||0)<100||(this.reduceMotion&&signature===this.previewSignature)))return;this.previewSignature=signature;this.prevFrame=now;if(!CSPreview.init())return;if(!CSPreview.H){CSPreview.H=makeHippo('#8fa3c4','#3b82f6',false,'CT');scene.remove(CSPreview.H.root);}const h=CSPreview.H;applyAgent(h,cfg.skins.agent);h.gun.visible=false;h.armsR.visible=false;h.armsP.visible=true;h.body.rotation.y=Math.PI+.2+(this.reduceMotion?0:Math.sin(now*.00035)*.25);h.root.position.set(0,0,0);h.body.position.y=0;const old=h.meshes.map(m=>m.material);const mat=this.material(cfg.vis.chamsMat,'preview')||{Flat:chamFlat,Metallic:chamMetal,Wireframe:chamWire,Glass:chamGlass}[cfg.vis.chamsMat]||chamVis;mat.color.set(cfg.vis.chamsColor);for(const m of h.meshes)m.material=mat;WhiteGlow46.sync(h,cfg.vis.chamsMat==='White Glow');CSPreview.S.add(h.root);const cam=new THREE.PerspectiveCamera(24,.85,1,1500);cam.position.set(0,48,238);cam.lookAt(0,43,0);CSPreview.r.setSize(272,320,false);if(CSPreview.r.domElement.parentNode!==parent)parent.appendChild(CSPreview.r.domElement);Render47.preview(CSPreview.S,cam);CSPreview.S.remove(h.root);h.meshes.forEach((m,i)=>m.material=old[i]);$('#vx-preview-label').textContent=cfg.vis.chamsMat;};
const vxUpdate=VisualFX.update;VisualFX.update=function(dt){vxUpdate.call(this,dt);ChamsFX.previewFrame();};
