const aaControlBase=control;control=function(it){if(it[0]==='aaState'){const r=document.createElement('div');r.className='nl-r';const l=document.createElement('span');l.textContent='Edit condition';const s=document.createElement('select');s.className='aa-state';for(const n of AA_STATES){const o=new Option(n,n,n===aaEditState,n===aaEditState);s.add(o);}s.onchange=()=>{aaEditState=s.value;renderTab();};r.append(l,s);return r;}if(it[0]==='aaLive'){const r=document.createElement('div');r.className='aa-live';const v=AntiAim.sample();r.textContent=v.state+' · real '+Math.round(v.real/DEG)+'° · fake '+Math.round(v.fake/DEG)+'° · Δ '+Math.round(v.delta)+'°';return r;}return aaControlBase(it);};
