const aaVisualUpdate=VisualFX.update;let aaLiveTimer=0;VisualFX.update=function(dt){aaVisualUpdate.call(this,dt);aaLiveTimer-=dt;if(aaLiveTimer<=0){aaLiveTimer=.2;const r=$('.aa-live');if(r){const v=AntiAim.sample();r.textContent=v.state+' · real '+Math.round(v.real/DEG)+'° · fake '+Math.round(v.fake/DEG)+'° · Δ '+Math.round(v.delta)+'°';}}};
function importConfigFile(){let input=$('#aa-cfg-upload');if(input)input.remove();input=document.createElement('input');input.type='file';input.accept='.txt,.json';input.id='aa-cfg-upload';input.hidden=true;document.body.appendChild(input);input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>131072)throw Error('CFG больше 128 КБ');let text=(await f.text()).trim();const raw=JSON.parse(text.startsWith('NL3:')?decodeURIComponent(escape(atob(text.slice(4)))):text);if(!raw||!raw.aa||!raw.rage||!raw.vis)throw Error('Неверный формат CFG');const schema=LuaHost.schema();
 const validate=(obj,def,path='')=>{const out=clone(def);for(const k of Object.keys(def)){if(!Object.hasOwn(obj,k))continue;const v=obj[k],d=def[k],p=path?path+'.'+k:k;if(Array.isArray(d)){if(!Array.isArray(v)||v.some(x=>typeof x!=='string'))throw Error('Неверное значение: '+p);out[k]=v.slice();}else if(d&&typeof d==='object'){if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Неверная группа: '+p);out[k]=validate(v,d,p);}else{if(typeof v!==typeof d||(typeof v==='number'&&!Number.isFinite(v)))throw Error('Неверный тип: '+p);const item=schema.get(p);if(item?.[0]==='slider'&&(v<item[3]||v>item[4]))throw Error('Вне диапазона: '+p);if(item?.[0]==='select'&&!item[3].includes(v))throw Error('Неизвестный режим: '+p);out[k]=v;}}return out;};
 const normalized=validate(raw,CFG_DEF);merge(cfg,normalized);LuaHost.rebaseOverrides();curPreset=f.name.replace(/\.(txt|json)$/i,'').slice(0,64);CFGS[curPreset]=LuaHost.baseCfg();saveCfgs();applyCfg();saveAll();renderTab();$('#nl-cfgname').textContent=curPreset;log('CFG loaded: '+esc(curPreset));SND.accept();}catch(e){log('Ошибка CFG: '+esc(e.message),'bad');}finally{input.remove();}};input.click();}
MENU[9].cols[1].find(g=>g.g==='Share').it.unshift(['button','Импорт CFG из файла',importConfigFile]);
