 const select=document.createElement('select');select.dataset.setting='wmPosition';for(const [value,label]of [['Right','Справа'],['Left','Слева']]){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o);}select.value=cfg.misc.wmPosition;select.onchange=()=>{cfg.misc.wmPosition=select.value;this.changed();};row('Положение',select);
