 `<svg viewBox="0 0 60 40" class="gsv"><path fill="${c}" d="M4 26c0-11 7-18 16-18s15 7 15 16v4H8z"/><path fill="rgba(0,0,0,.25)" d="M6 26h28v3H6z"/><path fill="${c}" d="M38 10h5l3 4 3-4h5l3 7-3 3v16H41V20l-3-3z"/></svg>`;
function buyMenu(open){const B=$('#buy');if(open===undefined)open=!buyOpen;if(open&&(G.state!=='game'||!player.alive||G.phase==='over'))open=false;buyOpen=open;B.style.display=open?'block':'none';buyCol=-1;
 if(open){mouseDown=false;if(document.pointerLockElement)document.exitPointerLock();renderBuy();SND.ui();if(pvInit()){const h=$('#bagent');if(h&&PV.r.domElement.parentNode!==h)h.appendChild(PV.r.domElement);pvAg=null;}}
 else if(G.state==='game'&&!menuOpen&&!chatOpen&&$('#pause').style.display!=='flex'&&!freeLook)lock();}
function itemInfo(id){if(GEAR[id])return{name:id==='helmet'?'Кевлар + шлем':'Кевлар',price:id==='helmet'&&player.armor>=100&&!player.helmet?350:GEAR[id].price,gear:1};const w=WEAPONS[WI[id]];return{name:w.name,price:w.price,w};}
