function buyLeft(){if(G.dm)return'∞';const s=G.phase==='freeze'?Math.ceil(G.freezeT)+20:Math.max(0,Math.ceil(G.time-95));return'00:'+String(Math.min(99,s)).padStart(2,'0');}
function renderBuy(){const B=$('#buy');if(rbRound!==G.round){if(roundBuys.length)lastBuys=roundBuys;roundBuys=[];rbRound=G.round;}const can=canBuy(),free=G.dm;
 if(!$('#bwrap')){B.innerHTML=`<div id="bwrap"><div class="bpanel"><div class="btime" id="btime"></div><div class="bcolsx" id="bcolsx"></div></div><div id="bagent"></div><div class="bown" id="bown"></div><div class="bmoney" id="bmoney"></div>
  <div class="bfoot"><span id="bf4">[F4] ПОВТОРИТЬ ЗАКУП</span><span id="bf3">[F3] АВТОЗАКУП</span><span id="bfx">[ESC] НАЗАД</span></div></div>`;$('#bf4').onclick=rebuy;$('#bf3').onclick=autoBuy;$('#bfx').onclick=()=>buyMenu(false);if(PV.r)$('#bagent').appendChild(PV.r.domElement);}
 $('#btime').innerHTML=can?`Время закупа <b>${buyLeft()}</b>`:'<span class="no">Время закупа истекло</span>';$('#bmoney').textContent=free?'$16000':'$'+player.money;
 let h='';BUYCS.forEach(([t,ids],ci)=>{h+=`<div class="bc ${buyCol===ci?'act':''}"><div class="bct"><i>${ci+1}</i>${t}</div>`;ids.forEach((id,k)=>{const I=itemInfo(id),o=owned(id),poor=!free&&player.money<I.price&&!o;const col=o?'#5b5f66':poor?'#6b6248':BY;
   const ic=I.gear?gearSvg(id,col):`<img src="${gunIcon(id,col,180,64)}">`;h+=`<div class="bi2 ${o?'own':''} ${poor?'poor':''} ${!can?'off':''}" data-id="${id}"><i>${k+1}</i><b>${I.name}</b>${ic}<span>$${I.price}</span></div>`;});h+='</div>';});
 $('#bcolsx').innerHTML=h;$('#bcolsx').querySelectorAll('.bi2').forEach(el=>{el.onmouseenter=()=>SND.ui();el.onclick=()=>{doBuy(el.dataset.id);renderBuy();};});
 $('#bown').innerHTML=[1,2,3,4].map(s=>WEAPONS.map((w,j)=>w.slot===s&&player.has[j]?`<img class="${player.weapon===j?'cur':''}" src="${gunIcon(w.id,'#ffffff',120,40)}">`:'').join('')).join('');}
function buyKey(n){if(n<1)return;if(buyCol<0){if(n<=BUYCS.length){buyCol=n-1;SND.ui();renderBuy();}return;}const id=BUYCS[buyCol][1][n-1];buyCol=-1;if(id)doBuy(id);renderBuy();}
function rebuy(){for(const id of lastBuys)doBuy(id);renderBuy();}
function autoBuy(){const m=()=>G.dm?99999:player.money;if(!owned('helmet'))doBuy(m()>=1000||player.armor>=100?'helmet':'kevlar');
 if(!WEAPONS.some((w,j)=>w.slot===1&&player.has[j])){for(const id of['awp','scar','m4','ak','ssg'])if(m()>=WEAPONS[WI[id]].price+(id==='awp'?300:0)){doBuy(id);break;}}
 if(m()>=1000&&!owned('dgl')&&!owned('r8'))doBuy('dgl');if(m()>=300)doBuy('he');if(m()>=300)doBuy('smoke');if(m()>=200)doBuy('flash');if(m()>=400)doBuy('molotov');if(m()>=50)doBuy('decoy');renderBuy();}
function buyFrame(dt){if(!buyOpen||!PV.r)return;const H=$('#bagent');if(!H)return;const w=H.clientWidth,hh=H.clientHeight;if(w<10||hh<10)return;
 if(pvAg!==cfg.skins.agent||pvGun!==W().id){pvAg=cfg.skins.agent;pvGun=W().id;pvSet(pvAg,W().nade||W().melee?'usp':W().id);PV.h.gunId=null;setHippoGun(PV.h,W().nade||W().melee?'usp':W().id,true);}
 setHippoGear(PV.h,player.helmet);pvFrame(w,hh,dt,Math.PI+.4,true);if(Math.random()<.1)$('#btime')&&($('#btime').innerHTML=canBuy()?`Время закупа <b>${buyLeft()}</b>`:'<span class="no">Время закупа истекло</span>');}

