document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===cv;if(locked&&(menuOpen||buyOpen||chatOpen||CursorControl.visible||G.state!=='game')){document.exitPointerLock();locked=false;return;}if(locked){$('#start').style.display='none';hidePause();}else if(G.state==='game'&&!CursorControl.visible&&!menuOpen&&!buyOpen&&!chatOpen&&G.phase!=='over'&&$('#start').style.display!=='flex')showPause();});
