function bindKey(code,down){for(const[k,b]of Object.entries(binds)){if(!b.key||b.key!==code)continue;if(b.mode==='Toggle'&&down){setP(k,!getP(k));log(`${LABELS[k]||k} ${getP(k)?'enabled':'disabled'}`);if(menuOpen)renderTab();}else if(b.mode==='Hold')setP(k,down);}}
addEventListener('keydown',e=>{if(e.target.tagName==='TEXTAREA'||e.target.isContentEditable||(e.target.tagName==='INPUT'&&e.target.type!=='range'&&e.target.type!=='color'))return;
 if(bindWait){e.preventDefault();const accepted=bindWait.cb(e.code);if(accepted!==false)bindWait=null;return;}
 if(e.code==='Insert'||e.code==='KeyM'||e.code==='Home'){e.preventDefault();toggleMenu();return;}
 if(e.code==='Escape'){if(menuOpen){toggleMenu(false);return;}if(buyOpen){buyMenu(false);return;}if(G.state==='menu'&&csView!=='home'){csView='';csGo('home');return;}if(G.state==='game'&&freeLook){if(G.paused)hidePause();else showPause();}return;}
 if(['Space','Tab','KeyQ','AltLeft'].includes(e.code)||(e.ctrlKey&&e.code!=='KeyC'))e.preventDefault();
 if(e.repeat){keys[e.code]=true;return;}keys[e.code]=true;if(G.state!=='game'||G.paused&&!G.mp)return;
 if(e.code==='KeyB'){buyMenu();return;}if(buyOpen){e.preventDefault();if(e.code==='F3')autoBuy();if(e.code==='F4')rebuy();const d=/^(Digit|Numpad)(\d)$/.exec(e.code);if(d)buyKey(+d[2]);return;}
 if((e.code==='KeyY'||e.code==='Enter')&&!menuOpen){e.preventDefault();chatOpenF();return;}
 bindKey(e.code,true);
 if(e.code==='KeyR')reload();if(e.code==='Digit1')slotSwitch(1);if(e.code==='Digit2')slotSwitch(2);if(e.code==='Digit3')slotSwitch(3);if(e.code==='Digit4')slotSwitch(4);if(e.code==='KeyQ')switchW(player.lastW);if(e.code==='KeyG'&&!vm.inspect)vm.inspect=1;});
addEventListener('keyup',e=>{keys[e.code]=false;if(G.state==='game')bindKey(e.code,false);});addEventListener('blur',()=>{for(const k in keys)keys[k]=false;mouseDown=mouse2=false;});
cv.addEventListener('mousedown',e=>{if(CursorControl.visible||menuOpen||buyOpen||chatOpen||G.state!=='game'||G.paused)return;if(!locked&&!freeLook){lock();return;}
 if(!player.alive&&!G.dm&&e.button===0){G.spec++;return;}
 if(e.button===3||e.button===4){bindKey('Mouse'+(e.button+1),true);return;}
 if(e.button===0)mouseDown=true;if(e.button===2){mouse2=true;if(W().scope&&player.alive&&!GN().reload){player.scope=(player.scope+1)%3;SND.zoom();}}});
addEventListener('mouseup',e=>{if(e.button===0)mouseDown=false;if(e.button===2)mouse2=false;if(e.button===3||e.button===4)bindKey('Mouse'+(e.button+1),false);});addEventListener('contextmenu',e=>e.preventDefault());
addEventListener('wheel',e=>{if(CursorControl.visible||menuOpen||buyOpen||chatOpen||GrenadeHelper49.modalOpen||G.paused||G.state!=='game')return;e.preventDefault();wheelJump=3;},{passive:false});
addEventListener('mousemove',e=>{if(CursorControl.visible||menuOpen||buyOpen||chatOpen||G.state!=='game'||G.paused||!(locked||freeLook))return;const z=!cfg.vis.third&&player.alive&&player.scope&&W().scope?(player.scope===1?.45:.18):1,k=sett.sens*.022*DEG*z;
 player.yaw-=e.movementX*k;player.pitch=clamp(player.pitch-e.movementY*k,-89*DEG,89*DEG);vm.swx=clamp(vm.swx-e.movementX*.00012,-.03,.03);vm.swy=clamp(vm.swy+e.movementY*.00012,-.03,.03);});
